BEGIN;

-- G検定 Set I (g-kentei-i) ブロック1: q1〜q16
-- カテゴリ「7. AIの社会実装に向けて」16問。viz 2問(q3対比, q11循環図)。
-- 個人情報保護法系の用語は本ブロックでは扱わない(このスキルの最重要ルール)。
-- subject/categories は作成済み。questions の INSERT のみ。

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-i-q1', '7. AIの社会実装に向けて',
   'データ分析プロジェクトの標準的な進め方であるCRISP-DMに対し、機械学習プロジェクト向けに拡張されたCRISP-MLが特に付け加えている工程はどれか。',
   NULL::text,
   '["CRISP-ML（本番運用後のモデル監視と再学習までを工程に含む拡張版）", "CRISP-DM（業務理解からデータ理解・準備・モデル作成・評価・展開までの型）", "アジャイル（短い期間で試作と修正を繰り返しながら進める開発の進め方）", "MLOps（機械学習の開発と運用を継続的に連携させる実践全般を指す語）"]',
   0,
   '[0]',
   'single',
   '{"asked": "CRISP-DMとCRISP-MLの違いで、CRISP-ML特有の工程を問う。", "point": "CRISP-DMは「展開」で終わるが、CRISP-MLは展開の後に「監視・保守」の工程が付く。", "kid": "CRISP-DMはデータ分析の進め方の型で、最後の「展開（世に出す）」で一区切り。CRISP-MLは機械学習向けにこの型を伸ばして、出した後もモデルの調子を見続けて、悪くなったら作り直す工程まで含めている。", "eg": "料理のレシピ本(CRISP-DM)は「盛り付けて完成」で終わる。でも生き物を飼うガイド本(CRISP-ML)は「迎え入れて終わり」ではなく「毎日の世話・体調管理・具合が悪ければ対処」まで書いてある。モデルは時間とともに古くなる生き物に近いので、世話の工程が要る。", "terms": [["CRISP-DM", "Cross-Industry Standard Process for Data Mining。業務理解→データ理解→データ準備→モデル作成→評価→展開の6段階でデータ分析を進める標準的な型"], ["CRISP-ML", "CRISP-DMを機械学習向けに拡張した型。展開の後にモデルの監視・保守・再学習の工程を明示的に含む"]], "think": "なぜ機械学習では「展開して終わり」にできないのかがカギ。CRISP-DMはもともと、統計分析やレポート作成のように、1回モデルを作って結果を出せば役目が終わるような分析を想定した型である。しかし機械学習で作ったモデルは、世の中のデータの傾向が変わるにつれて予測の精度がだんだん落ちていく性質を持つ。展開した時点がゴールではなく、そこからが本番の運用期間になる。CRISP-MLはこの性質をふまえ、展開の後に「モデルの状態を監視する」「精度が落ちたら再学習する」という工程を型そのものに組み込み、運用フェーズを工程の一部として明記した点がCRISP-DMとの違いになる。", "vs": "アジャイルは開発の進め方そのものの考え方（短い周期で試作と修正を繰り返す）を指す語で、データ分析の工程の型を指すCRISP-DM・CRISP-MLとは別のレイヤーの話。MLOpsは開発と運用を継続的に連携させる実践全般を指す広い語で、CRISP-MLはその考え方を工程の型として具体化したものの1つに位置づけられる。", "why_asked": "CRISP-DMは分析プロジェクトの型として広く知られているが、機械学習特有の「精度劣化」「再学習」という運用の観点が抜け落ちやすく、CRISP-MLとの違いとして問われやすい。", "usecase": "機械学習プロジェクトの計画を立てるとき、展開後の監視・再学習の体制まで最初から工程表に入れておく判断材料になる。", "opt": ["正解。本番運用後のモデル監視と再学習までを工程に含む、CRISP-DMの拡張版。", "業務理解からデータ理解・準備・モデル作成・評価・展開までの型で、運用後の監視は明示していない。", "短い期間で試作と修正を繰り返す開発の進め方で、分析工程の型そのものを指す語ではない。", "機械学習の開発と運用を継続的に連携させる実践全般を指す語で、工程の型そのものの名前ではない。"]}'),  ('g-kentei-i-q2', '7. AIの社会実装に向けて',
   '既存の業務のやり方はそのままに、その一部だけをAIに置き換えても効果が出にくいことが多い。業務プロセス自体を根本から見直し、AIの活用を前提に作り直すことを指す語はどれか。',
   NULL::text,
   '["BPR（業務プロセスを根本から見直し作り直すこと）", "PoC（本格導入の前に小規模な検証で実現可能性を確かめる工程）", "MLOps（機械学習の開発と運用を継続的に連携させる実践）", "アジャイル（短い期間で試作と修正を繰り返しながら進める開発の進め方）"]',
   0,
   '[0]',
   'single',
   '{"asked": "AI導入に合わせて業務プロセス自体を作り直すことを指す語を問う。", "point": "「既存業務にAIを貼るだけでは効果が出ない→プロセスごと作り直す」がBPR。", "kid": "今までのやり方をそのままにして、途中の1箇所だけをAIに変えても、あまり速くならないことが多い。BPRは、AIを使う前提で仕事の流れそのものを一から考え直すこと。", "eg": "紙の書類をハンコで回していた職場に、ハンコを押す部分だけAIに置き換えてもさほど速くならない。承認の流れそのものを電子化・自動化に合わせて作り直して、初めて仕事が本当に速くなる。この「流れごと作り直す」がBPR。", "terms": [["BPR", "Business Process Re-engineering＝業務プロセス・リエンジニアリング。業務の流れを根本から見直し作り直すこと"]], "think": "なぜ一部をAIに置き換えるだけでは効果が出にくいのかがカギ。多くの業務は、人が確認・判断・調整することを前提に手順が組まれている。その手順の一部だけをAIに差し替えても、前後の工程は人が確認する前提のまま残るため、待ち時間や二重チェックが残り、全体としては速くならないことが多い。BPRは、AIが得意なこと・人が得意なことを前提から考え直し、承認の階層を減らす、判断の順序を入れ替えるなど、業務プロセスそのものを作り直す取り組みである。AI導入で効果を出すには、技術の導入と業務プロセスの見直しをセットで行う必要がある。", "vs": "PoCは本格導入前に小規模な検証を行う工程であり、業務プロセスそのものを作り直す取り組みではない。MLOpsは機械学習の開発と運用を継続的に連携させる実践を指し、業務プロセス全体の見直しとは対象が異なる。アジャイルは開発の進め方の考え方であり、業務プロセスの再設計そのものを指す語ではない。", "why_asked": "「AIを導入したのに効果が出ない」という失敗パターンの原因として、技術の問題ではなく業務プロセス側の見直し不足が挙げられることが多く、その考え方の名前としてBPRが問われる。", "usecase": "AI導入プロジェクトの計画段階で、技術検証だけでなく業務フロー自体の再設計をあわせて進めるかどうかの判断に関わる。", "opt": ["正解。業務プロセスを根本から見直し作り直すこと。", "本格導入の前に小規模な検証で実現可能性を確かめる工程で、業務プロセスの作り直しそのものではない。", "機械学習の開発と運用を継続的に連携させる実践で、業務プロセス全体の再設計とは対象が異なる。", "短い期間で試作と修正を繰り返す開発の進め方で、業務プロセスの再設計そのものを指す語ではない。"]}'),  ('g-kentei-i-q3', '7. AIの社会実装に向けて',
   '要件定義・設計・開発・評価の各工程を順番に一度だけ進める開発スタイルに対し、モデルの精度が事前に約束できないAI開発では、短い期間で試作と検証を繰り返しながら進めるスタイルが好まれやすい。この開発スタイルはどれか。',
   NULL::text,
   '["アジャイル（短い期間で試作と検証を繰り返しながら進める開発スタイル）", "ウォーターフォール（各工程を順番に一度だけ進める開発スタイル）", "BPR（業務プロセスを根本から見直し作り直す取り組み）", "CRISP-DM（業務理解から展開までの一連の工程を定めた分析の型）"]',
   0,
   '[0]',
   'single',
   '{"asked": "精度が事前に約束できないAI開発で好まれやすい開発スタイルを問う。", "point": "「精度が事前に読めない→少しずつ作って確かめる」がアジャイル。", "kid": "ウォーターフォールは、最初に全部の計画を決めてから、順番に1回だけ滝のように上から下へ進めるやり方。アジャイルは、少し作っては試し、直しては試し、を短い周期で繰り返すやり方。", "eg": "旅行の計画で、出発前に全行程を分刻みで決めてその通りに動くのがウォーターフォール。まず1日目だけ大まかに動いてみて、様子を見ながら次の日の予定を決め直していくのがアジャイル。行き先の天気（AIなら精度）が事前に読めないなら、後者のほうが向いている。", "terms": [["ウォーターフォール", "要件定義・設計・開発・評価などの工程を、後戻りしない前提で順番に一度だけ進める開発スタイル"], ["アジャイル", "短い期間（数週間程度）で試作・検証・修正を繰り返しながら進める開発スタイル"]], "think": "なぜAI開発でアジャイルが好まれやすいのかがカギ。ウォーターフォールは、最初に要件と設計を確定させ、その通りに作れば期待通りの結果になるという前提の上に成り立つ進め方である。通常のシステム開発のように、仕様通りに作れば動くものはこの進め方と相性が良い。しかしAI開発では、実際にデータで学習させて評価してみるまで、どの程度の精度が出るかを事前に正確には約束できない。最初に立てた計画通りに進めても、期待した精度が出ない可能性が常にある。そこで、小さく作って実際のデータで検証し、その結果を見ながら次の一手を決めるアジャイルの進め方が、AI開発の不確実性に合っている。", "vs": "ウォーターフォールは工程を後戻りしない前提で一度だけ順に進めるスタイルで、精度が事前に読めないAI開発では計画とのズレが起きやすい。BPRは業務プロセスそのものを作り直す取り組みであり、開発の進め方そのものを指す語ではない。CRISP-DMは分析プロジェクトの工程の型であり、開発をウォーターフォール的に進めるかアジャイル的に進めるかとは別の軸の話。", "why_asked": "「AI開発は精度が読めないから計画通りに進まない」という前提を、開発スタイルの選び方（アジャイルが好まれる理由）まで結びつけて理解しているかが問われる。", "usecase": "AI開発プロジェクトの進め方を決めるとき、要件を最初に固めきれる部分はウォーターフォール的に、精度が読めないモデル作成部分はアジャイル的に進める、といった使い分けの判断に関わる。", "opt": ["正解。短い期間で試作と検証を繰り返しながら進める開発スタイル。", "各工程を順番に一度だけ進める開発スタイルで、精度が事前に読めないAI開発では計画とズレやすい。", "業務プロセスを根本から見直し作り直す取り組みで、開発の進め方そのものを指す語ではない。", "業務理解から展開までの一連の工程を定めた分析の型で、開発スタイルの選び方とは別の軸の話。"], "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">先に全部決めるか、少しずつ試して直すか</text><text x=\"85\" y=\"30\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">ウォーターフォール</text><rect x=\"30\" y=\"42\" width=\"45\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"52\" y=\"55\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">要件</text><rect x=\"80\" y=\"42\" width=\"45\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"102\" y=\"55\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">設計</text><rect x=\"30\" y=\"66\" width=\"45\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"52\" y=\"79\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">開発</text><rect x=\"80\" y=\"66\" width=\"45\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"102\" y=\"79\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">評価</text><line x1=\"75\" y1=\"51\" x2=\"80\" y2=\"51\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><line x1=\"52\" y1=\"60\" x2=\"52\" y2=\"66\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><line x1=\"75\" y1=\"75\" x2=\"80\" y2=\"75\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"66\" y=\"100\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">一直線に一度だけ進む</text><text x=\"66\" y=\"114\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">精度は事前に約束できない</text><line x1=\"170\" y1=\"22\" x2=\"170\" y2=\"132\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"255\" y=\"30\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">アジャイル</text><circle cx=\"220\" cy=\"60\" r=\"16\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"220\" y=\"63\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">作る</text><circle cx=\"255\" cy=\"45\" r=\"16\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"255\" y=\"48\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">試す</text><circle cx=\"290\" cy=\"60\" r=\"16\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"290\" y=\"63\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">直す</text><path d=\"M234 55 C 240 48, 246 48, 250 46\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><path d=\"M269 48 C 275 50, 280 55, 283 58\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><path d=\"M282 72 C 260 90, 235 85, 224 70\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\" stroke-dasharray=\"2 2\"/><text x=\"255\" y=\"100\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">短い周期を繰り返し回す</text><text x=\"255\" y=\"114\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">やりながら精度を確かめる</text></svg>"}'),  ('g-kentei-i-q4', '7. AIの社会実装に向けて',
   'AIプロジェクトが「最新技術を使ってみたいから」という動機だけで始まり、現場のニーズと結びつかないまま検証が終わってしまう失敗パターンを避けるために、企画の初期に確認すべきこととして最も適切なものはどれか。',
   NULL::text,
   '["ステークホルダーのニーズ（誰の、どんな課題を解決するプロジェクトかという確認）", "アジャイル（短い期間で試作と検証を繰り返しながら進める開発スタイルの選択）", "CRISP-DM（業務理解から展開までの一連の工程を定めた分析の型の採用）", "MLOps（機械学習の開発と運用を継続的に連携させる実践そのものへの早期着手）"]',
   0,
   '[0]',
   'single',
   '{"asked": "技術起点のAIプロジェクトが陥りがちな失敗を避けるため、企画初期に確認すべきことを問う。", "point": "「誰の何の課題を解決するのか」を最初に確認するのがステークホルダーのニーズの確認。", "kid": "「AIが流行っているから何か作ろう」で始めるのではなく、「困っている人は誰で、何に困っているのか」を最初にはっきりさせておくこと。", "eg": "新しい便利な工具を手に入れたからといって、それを使う日曲がった釘が身の回りに無ければ意味がない。まず「誰が、どんな作業で困っているか」を確認してから、その工具（AI）が本当に役立つかを考える順番が要る。", "terms": [["ステークホルダー", "そのプロジェクトの結果に利害関係を持つ人や組織。現場の担当者、利用者、経営層などを含む"]], "think": "なぜ技術起点のプロジェクトが失敗しやすいのかがカギ。「AIで何かできそうだ」という技術の可能性から企画が始まると、実際にそれを使う現場の人がどんな課題を抱え、どんな解決策なら受け入れられるかという視点が後回しになりやすい。その結果、技術的には動くものができても、現場の業務に合わず使われない、という結果になりがちである。ステークホルダーのニーズを企画の初期に確認するというのは、プロジェクトを始める前に「誰の」「どんな課題を」解決するのかを明確にし、その課題に対して本当にAIが有効な手段かどうかを見極めることを指す。この順番を守ることで、技術先行の失敗を防ぎやすくなる。", "vs": "アジャイルは開発の進め方の考え方であり、企画の初期に何を確認すべきかという論点とは別の話。CRISP-DMは分析工程の型であり、その最初の段階である業務理解の中でステークホルダーのニーズを確認することはあるが、CRISP-DM自体がニーズ確認という行為の名前ではない。MLOpsは開発と運用の連携の実践を指す語で、企画初期の確認事項とは異なる段階の話。", "why_asked": "「PoCをしたが精度は出たのに使われない」という失敗の根っこには、企画段階でのニーズ確認不足があることが多く、失敗を未然に防ぐ観点として問われやすい。", "usecase": "AIプロジェクトの企画書を書く最初の段階で、技術の紹介より先に「誰の何の課題か」を書く欄を設けるといった実務に直結する。", "opt": ["正解。誰の、どんな課題を解決するプロジェクトかを企画初期に確認すること。", "短い期間で試作と検証を繰り返す開発スタイルで、企画初期に何を確認すべきかという論点とは別の話。", "業務理解から展開までの分析工程の型で、ニーズ確認という行為そのものの名前ではない。", "開発と運用を継続的に連携させる実践で、企画初期の確認事項とは異なる段階の話。"]}'),  ('g-kentei-i-q5', '7. AIの社会実装に向けて',
   '自社の技術者や自社データだけでAI開発を完結させようとすると、専門知識やデータの不足が壁になることが多い。大学や他企業・他業種と手を組み、外部の知見やデータを取り入れながら開発を進める考え方はどれか。',
   NULL::text,
   '["オープン・イノベーション（外部の知見や技術を積極的に取り入れる考え方）", "BPR（業務プロセスを根本から見直し、AI導入に合わせて作り直す取り組み）", "アジャイル（短い期間で試作と検証を繰り返しながら進める開発スタイルの選択）", "MLOps（機械学習の開発と運用を継続的に連携させる実践そのものの実施）"]',
   0,
   '[0]',
   'single',
   '{"asked": "自前主義の限界を越えるため、大学や他企業と組んで開発を進める考え方を問う。", "point": "「自社だけで抱え込まず、外部の知見・データを取り入れる」がオープン・イノベーション。", "kid": "自分の会社の人だけ、自分の会社が持っているデータだけで頑張ろうとすると、知識や材料が足りなくなることがある。大学や他の会社の力も借りながら一緒に作っていく考え方。", "eg": "1人で料理のフルコースを作ろうとすると、材料の仕入れから盛り付けまで全部背負って大変になる。得意な人ごとに前菜・メイン・デザートを分担して作ってもらったほうが、質の高いコースになりやすい。AI開発でも、大学の研究力や他業種のデータを分担して借りることに近い。", "terms": [["産学連携", "企業と大学が協力して研究や開発を進める取り組み。オープン・イノベーションの代表的な形の1つ"], ["自前主義", "必要な技術や知見をすべて自社内でまかなおうとする考え方。オープン・イノベーションと対になる姿勢"]], "think": "なぜ自前主義には限界があるのかがカギ。AI開発には、最先端の理論を扱える専門人材、十分な量と質のデータ、実際に使ってみるための業務知識など、多くの要素が必要になる。1つの企業がこれらすべてを自社内だけでそろえようとすると、専門人材の確保やデータ量の不足が壁になりやすい。オープン・イノベーションは、この壁を自社の外に目を向けることで乗り越えようとする考え方である。大学と組めば最新の研究知見を、他業種の企業と組めば自社には無い種類のデータや業務知見を取り入れられる。1社で抱え込むより、それぞれの強みを持ち寄ったほうが、開発のスピードや質が上がりやすい。", "vs": "BPRは業務プロセスそのものを作り直す取り組みであり、外部との連携の考え方そのものを指す語ではない。アジャイルは開発の進め方の考え方で、誰と組んで開発するかという論点とは別の軸の話。MLOpsは開発と運用の連携の実践を指す語で、社外との連携を指す語ではない。", "why_asked": "AI開発を自社完結で進めようとして専門人材やデータの不足に行き詰まる失敗パターンが多く、その対策としての外部連携の考え方が問われる。", "usecase": "自社に無いデータや専門知識が必要な場面で、大学との共同研究や他業種の企業とのデータ連携を検討する判断材料になる。", "opt": ["正解。外部の知見や技術を積極的に取り入れる考え方。", "業務プロセスを根本から見直し作り直す取り組みで、外部との連携の考え方そのものではない。", "短い期間で試作と検証を繰り返す開発スタイルで、誰と組んで開発するかとは別の軸の話。", "開発と運用を継続的に連携させる実践で、社外との連携を指す語ではない。"]}'),  ('g-kentei-i-q6', '7. AIの社会実装に向けて',
   'AIプロジェクトの担い手として、ビジネス課題の理解・統計学的な分析力・システムを構築する実装力の3つの領域が交わるところに位置づけられる人材はどれか。',
   NULL::text,
   '["データサイエンティスト（ビジネス・統計・エンジニアリングの交点に立つ人材）", "ステークホルダー（プロジェクトの結果に利害関係を持つ人や組織を指す語）", "プロジェクトマネージャー（プロジェクト全体の進行や予算を管理する役割の担当者）", "アノテーター（学習データに正解ラベルなどを人手で付与する作業を行う担当者）"]',
   0,
   '[0]',
   'single',
   '{"asked": "ビジネス・統計・エンジニアリングの交点に位置づけられる人材の名前を問う。", "point": "「ビジネス課題の理解×統計分析力×実装力」の3つが重なる位置がデータサイエンティスト。", "kid": "「何に困っているか分かる力」「データを数字で読み解く力」「実際にシステムとして作る力」の3つを兼ね備えた、これらが重なるところに立つ人。", "eg": "レストランの新メニュー開発で、お客さんが何を求めているか(ビジネス)、材料の栄養バランスや味の組み合わせを分析する力(統計)、実際に厨房で再現できる調理技術(実装)の3つがそろって初めて、良いメニューが生まれる。データサイエンティストはこの3拍子を持つ人にあたる。", "terms": [["データサイエンティスト", "ビジネス課題の理解・統計学的な分析力・エンジニアリングによる実装力の3領域が交わる位置に立つ人材"]], "think": "なぜ3つの力の「交点」という表現になるのかがカギ。統計分析だけができても、それがビジネスのどんな課題に効くのかが分からなければ、分析結果は使われずに終わる。ビジネス課題は理解していても、実際にデータを分析し、モデルとしてシステムに組み込む実装力がなければ、アイデアは形にならない。データサイエンティストという役割は、この「ビジネス課題の理解」「統計学的な分析力」「システムを構築する実装力」のどれか1つに偏るのではなく、3つの領域を横断して橋渡しできる点に特徴がある。3つのどれか1つだけを担う専門職とは位置づけが異なる。", "vs": "ステークホルダーはプロジェクトに利害関係を持つ人全般を指す広い語で、特定の専門スキルを持つ役割の名前ではない。プロジェクトマネージャーは進行や予算の管理を担う役割で、統計分析力や実装力そのものを担う役割ではない。アノテーターは学習データに正解ラベルを付ける作業者を指し、3領域を横断する立場ではない。", "why_asked": "「データサイエンティスト=統計に詳しい人」という一面的な理解にとどまっていないか、ビジネス・統計・実装の3領域という定義を正確に押さえているかが問われる。", "usecase": "AIプロジェクトのチーム編成で、どの役割にどんなスキルセットを求めるかを整理するときの基準になる。", "opt": ["正解。ビジネス・統計・エンジニアリングの3領域が交わる位置に立つ人材。", "プロジェクトの結果に利害関係を持つ人や組織を指す広い語で、特定のスキルを持つ役割の名前ではない。", "プロジェクト全体の進行や予算を管理する役割で、統計分析力や実装力そのものを担う役割ではない。", "学習データに正解ラベルなどを付与する作業者で、3領域を横断する立場ではない。"]}'),  ('g-kentei-i-q7', '7. AIの社会実装に向けて',
   '「開発者の手元では動いたのに、本番のサーバーでは動かない」という、環境の違いによる不具合を防ぐため、アプリと必要なライブラリを1つにまとめて、どの環境でも同じように動かせるようにする技術はどれか。',
   NULL::text,
   '["Docker（アプリと環境を1つにまとめ、どこでも同じように動かす技術）", "Jupyter Notebook（コードと実行結果とメモを1つの画面にまとめるツール）", "Web API（学習済みモデルなどの機能を外部から呼び出せる形で提供する仕組み）", "クラウド（自前で機器を持たずに計算資源をインターネット経由で借りる仕組み）"]',
   0,
   '[0]',
   'single',
   '{"asked": "「私の環境では動いた」問題を防ぐ、環境をまとめて持ち運ぶ技術の名前を問う。", "point": "「環境ごとパッケージ化してどこでも同じ動作」と来たらDocker。", "kid": "パソコンの中に、必要なプログラムや設定をまるごと詰め込んだ「箱」を作っておいて、その箱ごと別のパソコンやサーバーに持っていけば、中身がそのまま同じように動く仕組み。", "eg": "自分のキッチン(手元のパソコン)で作った料理を、そのままお弁当箱(コンテナ)に詰めて持って行けば、よそのキッチン(本番サーバー)でも同じ味のまま食べられる。キッチンの調味料の配置が違っても、お弁当箱の中身は変わらない。", "terms": [["コンテナ", "アプリの実行に必要なライブラリや設定をひとまとめにした、持ち運び可能な軽量な実行環境"], ["「私の環境では動いた」問題", "開発者の手元では正常に動くが、ライブラリのバージョン違いなどで本番環境では動かなくなる典型的な不具合"]], "think": "なぜ環境の違いが不具合の原因になるのかがカギ。プログラムは、実行するパソコンやサーバーにどんなライブラリがどのバージョンで入っているかによって、動いたり動かなかったりすることがある。開発者の手元の環境と、本番のサーバーの環境が微妙に違うと、手元では正常に動いていたコードが本番では動かない、という事態が起きる。Dockerは、アプリ本体だけでなく、それが動くために必要なライブラリやOSの設定までをまとめて「コンテナ」という1つの箱に詰め込む。このコンテナごと別の環境に持っていけば、中身の環境がそのまま再現されるため、「私の環境では動いた」問題が起きにくくなる。", "vs": "Jupyter Notebookはコードと実行結果とメモを1つの画面にまとめる分析用のツールで、環境そのものを持ち運ぶ技術ではない。Web APIは学習済みモデルなどの機能を外部から呼び出せる形で提供する仕組みで、環境の再現とは別の目的の技術。クラウドは計算資源をインターネット経由で借りる仕組みであり、その計算資源の上でどんな環境を動かすかという問題を直接解決するものではない。", "why_asked": "AI開発では実験を重ねるうちに使うライブラリのバージョンが増えやすく、環境差による不具合が起きやすいため、その対策技術としてDockerの理解が問われる。", "usecase": "手元で学習させたモデルを本番のサーバーに載せるとき、コンテナごと持っていくことで環境差によるトラブルを避けられる。", "opt": ["正解。アプリと環境を1つにまとめ、どこでも同じように動かす技術。", "コードと実行結果とメモを1つの画面にまとめるツールで、環境そのものを持ち運ぶ技術ではない。", "学習済みモデルなどの機能を外部から呼び出せる形で提供する仕組みで、環境の再現とは別の目的の技術。", "計算資源をインターネット経由で借りる仕組みで、その上でどんな環境を動かすかを解決する技術ではない。"]}'),  ('g-kentei-i-q8', '7. AIの社会実装に向けて',
   'データ分析やAI開発の現場で、コードと実行結果のグラフ、それに気づいた点のメモまでを1枚の画面に並べて残せるため、プログラミング言語Pythonと組み合わせて標準的に使われているツールはどれか。',
   NULL::text,
   '["Jupyter Notebook（コードと実行結果とメモを1枚の画面にまとめるツール）", "Docker（アプリと必要な環境を1つにまとめ、どこでも同じように動かす技術のこと）", "クラウド（自前で機器を持たずに計算資源をインターネット経由で借りる仕組みのこと）", "Web API（学習済みモデルなどの機能を外部から呼び出せる形で提供する仕組みのこと）"]',
   0,
   '[0]',
   'single',
   '{"asked": "コードと結果とメモを1画面にまとめられる、Pythonとの定番の組み合わせツールを問う。", "point": "「コード・グラフ・メモが1枚にまとまる」と来たらJupyter Notebook。", "kid": "プログラムを少しずつ書いて実行しながら、その結果のグラフや表、気づいたことのメモまで、上から下へ1つのノートのように書きためていけるツール。", "eg": "実験ノートに、やったこと(コード)・出た結果のグラフ・気づいたコメントを、実験のたびにその場で書き足していくイメージ。あとで見返しても、何をしてどうなったかが1冊で追える。", "terms": [["Python", "AI・データ分析の分野で広く使われているプログラミング言語。読みやすい文法とライブラリの豊富さが特徴"], ["セル", "Jupyter Notebookでコードやメモを書き込む1つ1つの区画。区画ごとに実行し、結果をその場に表示できる"]], "think": "なぜデータ分析ではこの形式が標準になったのかがカギ。データ分析やAI開発では、コードを一気に最後まで書いて実行するのではなく、少しずつ試しながらデータの様子を確かめ、グラフを見て、次にどう処理するかを考える、という試行錯誤の繰り返しが多い。Jupyter Notebookは、コードを「セル」という小さな区画ごとに実行でき、その結果（数値やグラフ）をコードのすぐ下に表示できる。さらに文章のメモも同じ画面に書き込める。この「少しずつ試す」「結果をその場で見る」「気づきを書き残す」という3つが1つの画面でできることが、試行錯誤を重ねる分析作業と相性が良く、Pythonとあわせて分析現場の標準装備になっている。", "vs": "Dockerはアプリと環境をまとめて持ち運ぶ技術であり、コードを対話的に実行して結果を確認するためのツールではない。クラウドは計算資源を借りる仕組みであり、その計算資源の上でどう分析作業を進めるかというツールの選択とは別の話。Web APIは学習済みモデルの機能を外部から呼び出す仕組みで、分析中の試行錯誤を記録するツールではない。", "why_asked": "AIプロジェクトの進め方の中で、分析フェーズの実務にどんな道具が使われるかという実務寄りの知識として問われやすい。", "usecase": "データを読み込んで前処理し、グラフを描いて傾向を確かめ、モデルを試作するといった一連の分析作業を、1つの画面で行き来しながら進める場面で使われる。", "opt": ["正解。コードと実行結果とメモを1枚の画面にまとめるツール。", "アプリと必要な環境を1つにまとめ、どこでも同じように動かす技術で、対話的に結果を確認するツールではない。", "計算資源をインターネット経由で借りる仕組みで、分析作業の進め方のツールの選択とは別の話。", "学習済みモデルなどの機能を外部から呼び出す仕組みで、分析中の試行錯誤を記録するツールではない。"]}'),  ('g-kentei-i-q9', '7. AIの社会実装に向けて',
   '学習済みのモデルをアプリの内部に直接組み込むのではなく、モデルをサーバー側に置いておき、アプリ側からインターネット経由で呼び出して結果だけを受け取れるようにする提供の形はどれか。',
   NULL::text,
   '["Web API（インターネット経由で機能を呼び出せる形で提供する仕組み）", "Docker（アプリと必要な環境を1つにまとめ、どこでも同じように動かす技術）", "Jupyter Notebook（コードと実行結果とメモを1枚の画面にまとめるツール）", "クラウド（自前で機器を持たずに計算資源をインターネット経由で借りる仕組み）"]',
   0,
   '[0]',
   'single',
   '{"asked": "モデルをアプリに組み込まず、外部から呼び出せる形で提供する仕組みを問う。", "point": "「モデルを組み込まず、呼び出して結果だけ受け取る」と来たらWeb API。", "kid": "モデルという専門家を自分のアプリの中に住まわせるのではなく、専門家のいる窓口(サーバー)に電話やメールで質問を送って、答えだけをもらってくるイメージ。", "eg": "料理を作りたいとき、自分の家に専用の料理人を住まわせなくても、宅配サービスに電話で注文すれば料理(結果)だけ届けてもらえる。Web APIは、モデルという料理人を自分のアプリに住まわせず、必要なときだけ結果を届けてもらう仕組みに近い。", "terms": [["API", "Application Programming Interface。あるプログラムの機能を、別のプログラムから呼び出せるようにした窓口の取り決め"], ["Web API", "インターネット経由で呼び出せる形で提供されるAPI。学習済みモデルの機能提供によく使われる"]], "think": "なぜモデルをアプリに直接組み込まない選択肢が要るのかがカギ。モデルをアプリの内部に直接組み込む方式だと、モデルを更新するたびに、そのモデルを使っているすべてのアプリを作り直して配布し直す必要がある。また、モデル自体が大きく重い場合、それをアプリごとに持たせるのは無駄が多い。Web APIという提供の形では、モデルはサーバー側に1つだけ置いておき、複数のアプリはインターネット経由でリクエストを送って結果だけを受け取る。モデルを更新したいときはサーバー側だけを直せばよく、呼び出す側のアプリを直す必要はない。この分離が、モデルの提供と保守をしやすくしている。", "vs": "Dockerはアプリと環境をまとめて持ち運ぶ技術であり、モデルの提供方式そのものを指す語ではない。Jupyter Notebookはコードと結果をまとめる分析用のツールで、モデルを外部に提供する仕組みではない。クラウドは計算資源を借りる仕組みであり、Web APIをどこで動かすかの土台にはなるが、Web APIそのものとは別の概念。", "why_asked": "「学習済みモデルをどう配る・提供するか」はAIプロジェクトの展開フェーズで実務上よく出てくる論点で、その代表的な形としてWeb APIが問われる。", "usecase": "自社で作った画像認識モデルを、複数のスマホアプリやWebサービスから共通して使いたいときに、モデルをサーバーに置きWeb API経由で呼び出す構成にする。", "opt": ["正解。インターネット経由で機能を呼び出せる形で提供する仕組み。", "アプリと必要な環境を1つにまとめ、どこでも同じように動かす技術で、モデルの提供方式そのものではない。", "コードと実行結果とメモを1枚の画面にまとめるツールで、モデルを外部に提供する仕組みではない。", "計算資源をインターネット経由で借りる仕組みで、Web APIをどこで動かすかの土台とは別の概念。"]}'),  ('g-kentei-i-q10', '7. AIの社会実装に向けて',
   'AI開発に必要な高性能な計算機器を自社で購入せず、必要なときに必要な分だけインターネット経由で借りて使い、使わなくなれば返却できる仕組みはどれか。',
   NULL::text,
   '["クラウド（計算資源をインターネット経由で必要な分だけ借りる仕組み）", "Docker（アプリと必要な環境を1つにまとめ、どこでも同じように動かす技術）", "Web API（学習済みモデルなどの機能を外部から呼び出せる形で提供する仕組み）", "オープンデータセット（誰でも利用できる形で公開されているデータの集まり）"]',
   0,
   '[0]',
   'single',
   '{"asked": "計算機器を自前で持たず、必要な分だけ借りる仕組みを問う。", "point": "「GPUなどを買わずに、必要な分だけ借りて返せる」がクラウド。", "kid": "AIの学習には高性能なコンピュータがたくさんいるが、それを全部自分で買うと高くて場所も取る。必要なときだけインターネット経由で借りて、使い終わったら返せる仕組み。", "eg": "引っ越しのときに使うトラックを、毎日使うわけではないのに買ってしまうと置き場所に困る。必要な日だけレンタカーを借りるほうが合理的。クラウドは、高性能な計算機器を「レンタカーのように」必要な期間だけ借りる仕組みに近い。", "terms": [["GPU", "Graphics Processing Unit。もともと画像処理向けの計算装置だが、並列計算が得意でディープラーニングの学習にも広く使われる"], ["スモールスタート", "最初から大きな投資をせず、小さな規模で始めて様子を見ながら拡大していく進め方"]], "think": "なぜクラウドがスモールスタートと相性が良いのかがカギ。AIの学習、特にディープラーニングの学習には、GPUのような高価な計算機器が大量に必要になることが多い。これを自社で購入すると、初期費用が大きくかかるうえ、プロジェクトが小規模な実験段階でも高額な設備投資が必要になってしまう。クラウドを使えば、必要なときに必要な分だけ計算資源を借り、使い終わったら返却して費用を止められる。これにより、まずは小さく試してみて、うまくいきそうなら規模を広げるというスモールスタートがしやすくなる。買い切りの設備投資に比べて、始めるハードルと途中でやめるハードルの両方を下げられる点が特徴である。", "vs": "Dockerはアプリと環境をまとめて持ち運ぶ技術であり、計算機器そのものを借りる仕組みではない。Web APIはモデルの機能を外部から呼び出す仕組みであり、計算資源の調達方法とは別の話。オープンデータセットは公開されているデータの集まりを指し、計算機器の調達手段ではない。", "why_asked": "AI開発の立ち上げコストの話としてクラウドの利点が問われやすく、スモールスタートとの結びつきが正誤の分かれ目になる。", "usecase": "初めて機械学習を試すプロジェクトで、GPUを自社購入せずクラウド上で借りて試作し、効果が見えてから本格投資するかを判断する場面で使われる。", "opt": ["正解。計算資源をインターネット経由で必要な分だけ借りる仕組み。", "アプリと必要な環境を1つにまとめ、どこでも同じように動かす技術で、計算機器そのものを借りる仕組みではない。", "学習済みモデルなどの機能を外部から呼び出す仕組みで、計算資源の調達方法とは別の話。", "誰でも利用できる形で公開されているデータの集まりで、計算機器の調達手段ではない。"]}'),  ('g-kentei-i-q11', '7. AIの社会実装に向けて',
   'モデルをリリースした後も、時間の経過とともに予測精度が落ちていくことがあるため、精度の状態を継続的に確認し、必要に応じて再学習・再デプロイまでを回し続ける取り組みはどれか。',
   NULL::text,
   '["ヘルスモニタリングとライフサイクル管理（精度を監視し再学習まで回す取り組み）", "PoC（本格導入の前に小規模な検証で実現可能性を確かめる、開発前段階の工程）", "アノテーション（学習データに正解ラベルなどを人手で付与する、開発初期の作業）", "BPR（業務プロセスを根本から見直し、AI導入に合わせて作り直す取り組み）"]',
   0,
   '[0]',
   'single',
   '{"asked": "リリース後のモデルの精度を監視し続け、再学習まで回す取り組みを問う。", "point": "「出して終わりではなく、監視→劣化検知→再学習→再デプロイを回し続ける」がライフサイクル管理。", "kid": "モデルは1回作って世に出したら終わりではない。時間がたつと調子が悪くなることがあるので、定期的に様子を見て、悪くなっていたら作り直して、また出す、というのをずっと繰り返す取り組み。", "eg": "植木は植えて終わりではなく、毎日水をやり、元気がなければ肥料を変えたり植え替えたりを続けないと枯れてしまう。モデルも出した後、精度という元気さを見守り続け、悪くなったら手を入れ直す必要がある。", "terms": [["精度劣化", "運用後、世の中のデータの傾向が変わることなどにより、モデルの予測精度がだんだん落ちていく現象"], ["再学習", "新しいデータを使ってモデルを学習し直し、精度を回復・向上させること"]], "think": "なぜリリースした後こそが本番になるのかがカギ。モデルは、学習に使ったデータの傾向をもとに予測をするように作られている。ところが運用が始まると、世の中の状況や利用者の行動といったデータの傾向は時間とともに変化していく。学習した当時の傾向のままでは対応しきれなくなり、精度がだんだん落ちていくことがある。ヘルスモニタリングとライフサイクル管理は、この変化を見逃さないために、リリース後も精度などの指標を継続的に監視し、劣化を検知したら新しいデータで再学習し、再びリリースするというサイクルを回し続ける取り組みを指す。開発を終えた時点で仕事が終わるのではなく、運用そのものを継続的な管理の対象とする点が特徴である。", "vs": "PoCは本格導入前の小規模な検証を指し、リリース後の継続的な運用管理とは別の段階の話。アノテーションは学習データに正解ラベルを付与する作業で、モデルの運用後の監視とは異なる工程。BPRは業務プロセスそのものを作り直す取り組みで、モデル自体の精度を継続的に見守る取り組みとは対象が異なる。似た言葉にMLOpsがあるが、これは「開発・デプロイ・監視・再学習までを継続的に回し、開発と運用を密に連携させる」という進め方・体制づくりそのものの名前である。一方ヘルスモニタリングとライフサイクル管理は、そのMLOpsという実践の中で、リリース後に実際に行う「精度を見張り、劣化したら学習し直して出し直す」という具体的な取り組み内容を指す。MLOps=活動全体の呼び方、ヘルスモニタリングとライフサイクル管理=その中の運用後パートの中身、という関係でとらえるとよい。", "why_asked": "AIプロジェクトはリリースをゴールと誤解されやすく、その先に運用フェーズの管理が必要であるという理解を確認するために問われる。", "usecase": "本番運用中のレコメンドモデルなどで、定期的に精度指標を確認し、指標が落ちてきたら新しいデータで再学習して差し替える、という運用ルールを設計する場面で使われる。", "opt": ["正解。精度の状態を継続的に確認し、再学習・再デプロイまでを回し続ける取り組み。", "本格導入の前に小規模な検証で実現可能性を確かめる工程で、リリース後の継続的な運用管理とは別の段階。", "学習データに正解ラベルなどを人手で付与する作業で、モデルの運用後の監視とは異なる工程。", "業務プロセスを根本から見直し作り直す取り組みで、モデル自体の精度を見守る取り組みとは対象が異なる。"], "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">リリースして終わりではなく、回し続ける</text><circle cx=\"170\" cy=\"70\" r=\"52\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\" stroke-dasharray=\"2 2\"/><circle cx=\"170\" cy=\"25\" r=\"14\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"28\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">運用</text><circle cx=\"212\" cy=\"50\" r=\"14\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"212\" y=\"53\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">監視</text><circle cx=\"212\" cy=\"92\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.3\"/><text x=\"212\" y=\"95\" fill=\"#c47070\" font-size=\"7.5\" text-anchor=\"middle\">劣化検知</text><circle cx=\"170\" cy=\"116\" r=\"14\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"170\" y=\"119\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">再学習</text><circle cx=\"128\" cy=\"92\" r=\"14\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"128\" y=\"95\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">再デプロイ</text><circle cx=\"128\" cy=\"50\" r=\"14\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"128\" y=\"53\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">評価</text><path d=\"M184.6 33.7 Q 193.3 31.9, 195.7 40.3\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow)\"/><path d=\"M212 67 Q 218 70, 212 73\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow)\"/><path d=\"M197.2 100.4 Q 195.1 108.5, 186.5 106.6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow)\"/><path d=\"M155.2 107.6 Q 146.8 109.7, 144.5 101.4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow)\"/><path d=\"M128 75 Q 122 72.3, 128 69\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow)\"/><path d=\"M142.6 41.3 Q 144.8 33.1, 153.7 34.7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow)\"/><text x=\"170\" y=\"140\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">精度が落ちたら検知し、直して、また出す</text></svg>"}'),  ('g-kentei-i-q12', '7. AIの社会実装に向けて',
   '自然言語処理のモデルを学習させるために使われる、文章や会話などの言語データを大量に集めた集合のことを何と呼ぶか。',
   NULL::text,
   '["コーパス（言語データを大量に集めた集合）", "アノテーション（学習データに正解ラベルなどを人手で付与する作業）", "オープンデータセット（誰でも利用できる形で公開されているデータの集まり）", "データリーケージ（本来使えない情報が学習データに紛れ込んでしまう現象）"]',
   0,
   '[0]',
   'single',
   '{"asked": "自然言語処理の学習に使う、言語データの集まりを指す語を問う。", "point": "「文章・会話などの言語データを大量に集めた集合」がコーパス。", "kid": "新聞記事やSNSの投稿、本の文章など、たくさんの文章を集めた「言葉のかたまり」。これを使ってモデルに言葉の使い方を学ばせる。", "eg": "外国語を覚えるとき、辞書だけでなく、実際にたくさんの新聞や小説を読み込むことで、単語の使われ方や言い回しの感覚を身につける。コーパスは、モデルにとってのこの「大量の読み込み教材」にあたる。", "terms": [["自然言語処理", "人間が使う言葉（自然言語）をコンピュータで処理・分析する技術分野"]], "think": "なぜ自然言語処理にコーパスが要るのかがカギ。言葉の意味や使われ方は、辞書の定義だけでは十分にとらえきれない。同じ単語でも文脈によって意味合いが変わったり、よく一緒に使われる単語の組み合わせがあったりする。こうした言葉の実際の使われ方を学ばせるには、実際に書かれた・話された大量の文章、つまりコーパスが必要になる。モデルはこの大量の言語データの中から、単語どうしのつながり方や文章の構造といったパターンを学び取っていく。コーパスの量や質が、そのモデルがどれだけ自然な言葉の使い方を学べるかに直結する。", "vs": "アノテーションは学習データに正解ラベルなどを人手で付与する作業を指し、言語データそのものの集合であるコーパスとは別の概念（コーパスにアノテーションを付けることもある）。オープンデータセットは無料や公開の形で使えるデータ全般を指す広い語で、言語データに限らない。データリーケージは学習データに本来使えない情報が紛れ込む問題であり、コーパスという言語データの集合そのものを指す語ではない。", "why_asked": "「コーパス」は自然言語処理の基礎用語として頻出だが、単なる「文章の集まり」以上の意味（学習素材としての位置づけ）まで理解しているかが問われる。", "usecase": "文章の分類モデルや文章生成モデルを作るとき、どんな種類・量のコーパスで学習させたモデルかによって、得意な文体や話題の傾向が変わってくる。", "opt": ["正解。言語データを大量に集めた集合。", "学習データに正解ラベルなどを人手で付与する作業で、言語データの集合そのものを指す語ではない。", "誰でも利用できる形で公開されているデータの集まりを指す広い語で、言語データに限らない。", "本来使えない情報が学習データに紛れ込んでしまう現象で、言語データの集合そのものを指す語ではない。"]}'),  ('g-kentei-i-q13', '7. AIの社会実装に向けて',
   'ImageNetのように、研究や開発のために無料で公開され誰でも利用できるデータの集まりについて、利用する際の注意点として最も適切なものはどれか。',
   NULL::text,
   '["無料で使えても、利用条件やライセンスに従う必要がある。", "無料で公開されている以上、利用条件を確認せず自由に使ってよい。", "公開されているデータは学習用途に限り、評価用途には使えない。", "公開されているデータは商用のAI開発では一切利用できない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "オープンデータセットを利用する際に注意すべきことを問う。", "point": "「無料公開＝無条件で自由に使える」ではなく、利用条件・ライセンスの確認が要る。", "kid": "無料で配られているデータでも、「こういう使い方ならOK」「こういう使い方はダメ」という決まりが付いていることが多い。使う前にその決まりを確認する必要がある。", "eg": "図書館の本は無料で読めるが、コピーして配ってよいかどうかには別のルール(著作権)がある。オープンデータセットも、無料で手に入るからといって、そのルールを読まずに何にでも使ってよいわけではない。", "terms": [["オープンデータセット", "研究や開発のために無料で公開され、誰でも利用できるデータの集まり。ImageNetなどが代表例"], ["ライセンス", "そのデータや作品を、誰が・どんな目的で・どこまで利用してよいかを定めた取り決め"]], "think": "なぜ「無料」と「自由に使える」がイコールにならないのかがカギ。オープンデータセットは、研究や開発を後押しするために無料で公開されているものが多いが、その公開のしかたには、たいてい利用条件やライセンスが付いている。例えば「研究目的なら無料だが商用利用には別途許諾が必要」「出典を明記すれば利用できる」といった条件が定められていることがある。データを無料で入手できることと、そのデータをどんな目的にでも自由に使ってよいこととは別の話であり、実際に使う前には、そのデータセットに付いているライセンスの内容を確認する必要がある。", "vs": "「利用条件を確認せず自由に使ってよい」は、無料公開であることと利用条件が無いことを混同した誤り。「学習用途に限り評価用途には使えない」「商用のAI開発では一切利用できない」は、いずれもデータセットごとに条件が異なるにもかかわらず一律に決めつけている点が誤り。実際にどこまで使えるかは、そのデータセットに付いているライセンスの内容次第である。", "why_asked": "「オープン＝無料＝何でも自由」という誤解はよくある落とし穴で、公開データにも利用条件があるという注意点が問われやすい。", "usecase": "研究で公開されているデータセットを使って商用製品のモデルを学習させたい場合に、そのデータセットのライセンスが商用利用を許しているかを事前に確認する場面で使われる。", "opt": ["正解。無料で使えても、利用条件やライセンスに従う必要がある。", "無料で公開されている以上、利用条件を確認せず自由に使ってよい、というのは誤り。", "公開データが学習用途に限られ評価用途に使えないかどうかは、データセットごとの条件次第で一律には決まらない。", "公開データが商用のAI開発で一切利用できないかどうかも、データセットごとの条件次第で一律には決まらない。"]}'),  ('g-kentei-i-q14', '7. AIの社会実装に向けて',
   '複数の作業者がアノテーション（正解ラベルの付与）を行うとき、人によって判断がばらついてしまう問題を減らすための取り組みとして最も適切なものはどれか。',
   NULL::text,
   '["作業ガイドラインを整備し、複数人での判断の一致を確認する。", "作業者ごとの判断基準は個性としてそのまま尊重し、統一は行わない。", "最初の1人が付けたラベルをそのまま採用し、他の作業者には確認させない。", "作業のスピードを最優先し、判断基準の確認は開発の最後にまとめて行う。"]',
   0,
   '[0]',
   'single',
   '{"asked": "複数人で行うアノテーションの判断のばらつきを減らす取り組みを問う。", "point": "「作業ガイドラインを整え、複数人の判断の一致を確認する」がアノテーションの品質管理。", "kid": "同じ写真を見ても、人によって「これは猫」「いや微妙」と判断が分かれることがある。あらかじめ判断のルールを紙に書いておいて、複数人で同じ判断になるか確認しながら進めることで、ラベルのばらつきを減らす。", "eg": "運動会の徒競走で、審判が複数人いるのに「1着はこの子」という判定がバラバラだと大混乱になる。事前に「どこがゴールラインか」「同着はどう扱うか」を審判全員で確認しておけば、判定はそろいやすくなる。アノテーションの判断基準も同じで、事前にそろえておく必要がある。", "terms": [["アノテーション", "学習データに正解ラベルや境界などの情報を人手で付与する作業"], ["作業ガイドライン", "アノテーション作業で、何をどう判断してラベルを付けるかを定めた手順書"], ["一致率", "複数の作業者が同じデータに同じ判断をした割合。アノテーションの品質を確認する指標の1つ"]], "think": "なぜ判断がばらつくとモデルの学習に困るのかがカギ。アノテーションで付けられた正解ラベルは、モデルにとって「正しい答え」そのものになる。ここに作業者ごとの判断のブレが混ざると、モデルは矛盾した答えを正解として学習することになり、精度の低下につながる。この問題を減らすには、まず「何をどう判断してラベルを付けるか」を明文化した作業ガイドラインを用意し、作業者全員がそれに沿って判断できるようにする。そのうえで、同じデータを複数人に判断させて、その判断がどれだけ一致するかを確認することで、基準がぶれている箇所を見つけて修正していく。この2段構えが、アノテーションの品質を保つ取り組みになる。", "vs": "「作業者ごとの判断基準を個性として尊重し統一しない」は、正解ラベルとしての一貫性が失われるため品質管理としては誤り。「最初の1人のラベルをそのまま採用し他の作業者に確認させない」は、判断のばらつきを見つける機会そのものを失う。「作業のスピードを最優先し確認は最後にまとめて行う」は、途中でのばらつきの修正機会を逃し手戻りが大きくなりやすい。", "why_asked": "「アノテーションとは何か」という定義は既に押さえていても、複数人で作業したときの品質管理という運用の観点は見落とされやすく、そこが問われる。", "usecase": "大量の画像に複数の作業者でラベルを付けるプロジェクトで、作業開始前にガイドラインを整備し、序盤で一致率を確認してから本作業に進む、という進め方に使われる。", "opt": ["正解。作業ガイドラインを整備し、複数人での判断の一致を確認する。", "作業者ごとの判断基準を個性として尊重し統一しないのは、正解ラベルの一貫性を失わせる。", "最初の1人のラベルをそのまま採用し他の作業者に確認させないのは、ばらつきを見つける機会を失う。", "作業のスピードを最優先し確認を最後にまとめて行うのは、途中の修正機会を逃し手戻りが大きくなる。"]}'),  ('g-kentei-i-q15', '7. AIの社会実装に向けて',
   '複数の企業でデータを持ち寄って共同でAI開発を進める場合、開発を始める前に取り決めておくべきこととして最も適切なものはどれか。',
   NULL::text,
   '["データの持ち出せる範囲や成果物の権利関係を先に決めておく。", "まず開発を進めてみて、データの扱いや権利関係は完成後にまとめて話し合う。", "参加する企業のうち技術力が最も高い企業が、全データを自由に扱ってよいとする。", "共有するデータの範囲は決めず、必要になったつどその場で判断する。"]',
   0,
   '[0]',
   'single',
   '{"asked": "複数企業でのデータ共有をともなう共同開発で、事前に取り決めるべきことを問う。", "point": "「開発が始まってからでは遅い。データの持ち出し範囲・権利関係は先に決める」のが鉄則。", "kid": "違う会社どうしでデータを出し合って一緒に開発するとき、「どのデータをどこまで外に持ち出していいか」「できあがった成果は誰のものか」を、作業を始める前に決めておく必要がある。", "eg": "友達と共同で家を建てるとき、材料を誰がどれだけ出したか、できた家は誰の名義になるかを決めないまま工事を始めると、後で大きなもめごとになる。データを持ち寄る共同開発も同じで、着工前(開発前)の取り決めが要る。", "terms": [["共同開発", "複数の企業や組織が、それぞれのデータや技術を持ち寄って1つの成果を目指す開発の形"]], "think": "なぜ「先に決める」ことが重要なのかがカギ。共同開発では、参加する各企業が自社のデータをどこまで開発チーム内で共有してよいか、開発の過程でそのデータがどう使われるか、完成した成果物やそこから生まれた知的財産権を誰がどう持つかといった論点がある。これらを開発が進んでから話し合おうとすると、すでにデータが混ざり合って使われた後になり、「そのデータはどこまで使ってよかったのか」を後から切り分けるのが難しくなる。開発を始める前に、データの持ち出せる範囲と成果物の権利関係の大枠を取り決めておくことで、後になってのトラブルを防ぎやすくなる。具体的な契約の類型（請負・準委任など。詳しくは契約を扱う章で改めて出てくる）を細かく詰めるのは別の論点だが、運用面としてこの順番を守ることが土台になる。", "vs": "「まず開発を進めて完成後にまとめて話し合う」は、データがすでに混ざった後では切り分けが難しくなるため運用上のリスクが大きい。「技術力が最も高い企業が全データを自由に扱ってよい」は、他の参加企業の権利や意向を無視した進め方で、対等な共同開発の前提を崩す。「共有範囲を決めずその場で判断する」は、判断基準が場当たり的になり、後から見返しても一貫した説明ができなくなる。", "why_asked": "技術面の議論に注目が集まりがちだが、複数社が関わる開発では、データの扱いという運用面の取り決めが後回しにされてトラブルになる例があり、そこが問われる。", "usecase": "複数企業が参加する共同のAI開発プロジェクトを立ち上げる際、キックオフの段階でデータの持ち出し範囲や成果物の扱いを確認する場面で使われる。", "opt": ["正解。データの持ち出せる範囲や成果物の権利関係を先に決めておく。", "まず開発を進め完成後にまとめて話し合うのは、データが混ざった後では切り分けが難しくなる。", "技術力が最も高い企業が全データを自由に扱ってよいとするのは、他社の権利や意向を無視した進め方になる。", "共有範囲を決めずその場で判断するのは、基準が場当たり的になり後から説明できなくなる。"]}'),  ('g-kentei-i-q16', '7. AIの社会実装に向けて',
   'PoC（概念実証）でモデルの精度が十分に確認できたにもかかわらず、実際の業務では使われずに終わってしまうことがある。この失敗の主な原因として最も適切なものはどれか。',
   NULL::text,
   '["現場のオペレーションに組み込むための業務プロセスの見直しが伴っていない。", "PoCの段階でモデルの精度指標を一切確認していなかったこと。", "PoCに使ったデータの量が、本番運用よりも多すぎたということ。", "PoCで使ったプログラミング言語が、本番システムと同じだったということ。"]',
   0,
   '[0]',
   'single',
   '{"asked": "PoCで精度が出たのに実際の業務に定着しない失敗の主な原因を問う。", "point": "「精度は出た。でも現場の仕事の流れに組み込む見直しをしていない」がこの壁の正体。", "kid": "テストではうまくいったのに、実際の仕事の現場では使われないままになってしまうことがある。原因の多くは、モデルの精度の問題ではなく、「その結果を現場でどう使うか」という仕事の流れ側が変わっていないこと。", "eg": "新しい高性能な自転車(モデル)を手に入れても、家の前の道が階段だらけ(既存の業務の流れ)のままでは、結局使われずに物置に置かれたままになる。自転車の性能を活かすには、道(業務プロセス)のほうも整える必要がある。", "terms": [["PoC", "Proof of Concept＝概念実証。本格導入の前に小規模な検証を行い、技術的な実現可能性や効果を見極める工程"], ["現場のオペレーション", "実際の業務で担当者が日々行っている作業や判断の流れ"]], "think": "なぜ精度が出ているのに使われないのかがカギ。PoCは、限定された条件のもとでモデルが技術的に機能するかどうかを確かめる工程であり、その結果が良好であることは、モデルの予測性能に問題が無いことを示す。しかし、実際の業務でその予測結果を使うには、現場の担当者がその結果をどう受け取り、どう判断に反映し、既存の作業手順のどこに組み込むかという、業務プロセス側の受け皿が必要になる。この受け皿となる業務プロセスの見直し（BPRに近い取り組み）が伴っていないと、精度の良いモデルができていても、現場では「結局どう使えばいいか分からない」「今までのやり方のほうが早い」となり、定着しないまま終わってしまう。この壁を越えるには、PoCの段階から現場の運用フローまで見据えて設計する必要がある。", "vs": "「PoCの段階でモデルの精度指標を一切確認していなかった」は、そもそも精度が確認できているという前提と矛盾する。「PoCに使ったデータの量が本番運用より多すぎた」「PoCで使ったプログラミング言語が本番システムと同じだった」は、いずれも業務に定着しない主な原因としては的外れで、現場の使われ方という論点からずれている。", "why_asked": "PoCという工程自体の定義は理解していても、その先の「なぜ精度が出たのに使われないのか」という失敗パターンとBPRとの結びつきまでは見落とされやすく、そこが問われる。", "usecase": "PoCで良い結果が出た後、そのまま展開に進む前に、現場の作業手順のどこにその結果を組み込むかを設計し直す、という次の一手を判断する場面で使われる。", "opt": ["正解。現場のオペレーションに組み込むための業務プロセスの見直しが伴っていない。", "PoCの段階で精度指標を一切確認していなかった、というのは精度が確認できている前提と矛盾する。", "PoCに使ったデータの量が本番運用より多すぎたことは、業務に定着しない主な原因としては的外れ。", "PoCで使ったプログラミング言語が本番システムと同じだったことは、業務に定着しない原因としては的外れ。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-i'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
